private readonly Dictionary<string, WeakReference<ImageData>> _cache = new();

public ImageData? GetImage(string key)
{
    if (_cache.TryGetValue(key, out var weak) && weak.TryGetTarget(out var img))
        return img;
    var loaded = LoadFromDisk(key);
    _cache[key] = new WeakReference<ImageData>(loaded);
    return loaded;
}
